INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10301, '1 Chronicles 22:9', '1 Chronicles', 22, 9, '&nbsp;خو هغۀ بيا هم ما سره يوه وعده وکړه چې، ستا به يو زوئ پېدا شى چې هغه به په امن سره حکومت کوى، ځکه چې زۀ به هغۀ له د هغۀ د ټولو ګېرچاپېره دشمنانو نه امن ورکړم. د هغۀ نوم به سليمان وى، ځکه چې د هغۀ په بادشاهۍ کښې به زۀ بنى اِسرائيلو له امن او سلامتى ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10302, '1 Chronicles 22:10', '1 Chronicles', 22, 10, '&nbsp;هغه به زما دپاره يو کور جوړ کړى. هغه به زما زوئ وى او زۀ به د هغۀ پلار يم. هغه او د هغۀ اولاد به د تل دپاره په بنى اِسرائيلو باندې بادشاهى کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10303, '1 Chronicles 22:11', '1 Chronicles', 22, 11, '&nbsp;داؤد خپله خبره جارى وساتله، ”نو زما زويه، مالِک خُدائ ستا خُدائ پاک دې ستا مل شى او هغه دې خپله وعده پوره کړى چې تا د هغۀ دپاره په کور جوړولو کښې کامياب کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10304, '1 Chronicles 22:12', '1 Chronicles', 22, 12, '&nbsp;او مالِک خُدائ ستا خُدائ پاک دې پوهه او حِکمت درکړى نو تۀ به د هغۀ د قانون په مطابق په بنى اِسرائيلو باندې حکومت وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10305, '1 Chronicles 22:13', '1 Chronicles', 22, 13, '&nbsp;کۀ تۀ هغه ټول قانون ومنې کوم چې مالِک خُدائ موسىٰ له د بنى اِسرائيلو دپاره ورکړے وو، نو تۀ به کامياب يې. تکړه شه او حوصله مضبوطه کړه او چې د هيڅ نه هم ونۀ يرېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10306, '1 Chronicles 22:14', '1 Chronicles', 22, 14, '&nbsp;او د مالِک خُدائ د کور دپاره ما په خپل ډېر کوشش سره څلور زره ټنه سرۀ زر او کم از کم څلوېښت زره ټنه سپين زر راغونډ کړى دى چې د دې په جوړولو کښې استعمال شى. د دې نه علاوه بې‌حسابه اوسپنه او زېړ هم دى. ما څۀ لرګى او کاڼى هم تيار کړى دى، خو تۀ به نور هم تياروې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10307, '1 Chronicles 22:15', '1 Chronicles', 22, 15, '&nbsp;تا سره ډېر د کار والا سړى دى. د کاڼو جوړولو دپاره سړى شته او ګِلکاران او ترکاڼان شته، هم داسې په لوئ شمېر کښې اُستاذان موجود دى چې هر قِسم کار کولے شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10308, '1 Chronicles 22:16', '1 Chronicles', 22, 16, '&nbsp;لکه د سرو زرو، سپينو زرو، زېړو او اوسپنې. اوس کار شروع کړه او مالِک خُدائ دې ستا مل شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10309, '1 Chronicles 22:17', '1 Chronicles', 22, 17, '&nbsp;داؤد د بنى اِسرائيلو ټولو مشرانو له حُکم ورکړو چې د سليمان مدد وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10310, '1 Chronicles 22:18', '1 Chronicles', 22, 18, '&nbsp;هغۀ وفرمائيل، ”مالِک خُدائ ستاسو خُدائ پاک ستاسو مل دے او په هر طرف باندې يې خېر درکړے دے. هغۀ په ما باندې هغه ټول خلق فتح کړل کوم چې په دې مُلک کښې اوسېدل او هغوئ اوس ستاسو او د مالِک خُدائ لاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10311, '1 Chronicles 22:19', '1 Chronicles', 22, 19, '&nbsp;نو اوس د زړۀ د اخلاصه د مالِک خُدائ د خپل خُدائ پاک لټون وکړئ. د مالِک خُدائ کور جوړول شروع کړئ، نو چې تاسو په هغې کښې د مالِک خُدائ د لوظ صندوق او هغه نور ټول مقدس سامان کېږدئ چې د هغۀ په عبادت کښې استعماليږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10312, '1 Chronicles 23:1', '1 Chronicles', 23, 1, '&nbsp;کله چې داؤد د ډېر عُمر شو، نو هغۀ خپل زوئ سليمان د بنى اِسرائيلو بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10313, '1 Chronicles 23:2', '1 Chronicles', 23, 2, '&nbsp;داؤد بادشاه د بنى اِسرائيلو ټول مشران، ټول اِمامان او ليويان راغونډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10314, '1 Chronicles 23:3', '1 Chronicles', 23, 3, '&nbsp;هغۀ د هغه ټولو نرانو ليويانو مردم‌شمارى وکړه چې عُمر يې دېرش کاله يا د دې نه زيات وو. دا ټول شمېر اتۀ دېرش زره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10315, '1 Chronicles 23:4', '1 Chronicles', 23, 4, '&nbsp;بادشاه د دې ليويانو نه څليريشت زره کسان مقرر کړل چې د مالِک خُدائ د کور د کار اِنتظام وکړى، شپږ زره کسان چې اِنتظام چلوى او لانجې هواروى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10316, '1 Chronicles 23:5', '1 Chronicles', 23, 5, '&nbsp;څلور زره کسان د څوکيدارۍ دپاره او څلور زره کسان د مالِک خُدائ د حمد‌و‌ثناء وئيلو دپاره. هغوئ د موسيقۍ هغه څيزونه استعمالول چې بادشاه د دې دپاره ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10317, '1 Chronicles 23:6', '1 Chronicles', 23, 6, '&nbsp;داؤد ليويان په درېو ډلو کښې د هغوئ د قبيلو په مطابق تقسيم کړل، جيرسون، قُهات او مرارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10318, '1 Chronicles 23:7', '1 Chronicles', 23, 7, '&nbsp;د جيرسون دوه زامن وُو، لعدان او سِمعى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10319, '1 Chronicles 23:8', '1 Chronicles', 23, 8, '&nbsp;د لعدان درې زامن وُو، مشر يحى‌ايل، ورپسې زيتان او يوايل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10320, '1 Chronicles 23:9', '1 Chronicles', 23, 9, '&nbsp;چې هغوئ د هغه ډلو مشران وُو چې د لعدان اولاد وو. د سِمعى درې زامن وُو، سلوميت، حزى‌اېل او حاران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10321, '1 Chronicles 23:12', '1 Chronicles', 23, 12, '&nbsp;د قُهات څلور زامن وُو، عُمرام، اِضهار، حبرون او عُزى‌اېل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10322, '1 Chronicles 23:13', '1 Chronicles', 23, 13, '&nbsp;د هغۀ مشر زوئ عُمرام د هارون او موسىٰ پلار وو. هارون او د هغۀ اولاد د دې دپاره مخصوص کړے شوى وُو چې د همېشه دپاره د مقدسو څيزونو مشران وى، چې د مالِک خُدائ په عبادت کښې خوشبوئى سوزوى، د هغۀ خِدمت کوى او د مالِک خُدائ په نوم باندې د خلقو دپاره برکت غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10323, '1 Chronicles 23:14', '1 Chronicles', 23, 14, '&nbsp;خو د خُدائ پاک د خِدمتګار موسىٰ زامن په ليويانو کښې شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10324, '1 Chronicles 23:15', '1 Chronicles', 23, 15, '&nbsp;د موسىٰ دوه زامن وُو، جيرسوم او اِلى‌عزر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10325, '1 Chronicles 23:16', '1 Chronicles', 23, 16, '&nbsp;د جيرسوم په زامنو کښې مشر سبو‌اېل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10326, '1 Chronicles 23:17', '1 Chronicles', 23, 17, '&nbsp;د اِلى‌عزر صِرف يو زوئ رحبياه وو، خو د رحبياه بچى ډېر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10327, '1 Chronicles 23:18', '1 Chronicles', 23, 18, '&nbsp;د قُهات د دوېم زوئ اِضهار، زوئ سلوميت وو چې د قبيلې مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10328, '1 Chronicles 23:19', '1 Chronicles', 23, 19, '&nbsp;د قُهات درېم زوئ حبرون څلور زامن وُو، يرياه، امرياه، يحزى‌ايل او يقمعام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10329, '1 Chronicles 23:20', '1 Chronicles', 23, 20, '&nbsp;د قُهات د څلورم زوئ عُزى‌اېل دوه زامن ميکاه او يسياه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10330, '1 Chronicles 23:21', '1 Chronicles', 23, 21, '&nbsp;د مرارى دوه زامن محلى او موشى وُو. د محلى هم دوه زامن اِلى‌عزر او قيس وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10331, '1 Chronicles 23:22', '1 Chronicles', 23, 22, '&nbsp;خو د اِلى‌عزر زامن نۀ وُو، صِرف لوڼه يې وې او بې‌زامنو مړ شو. د هغۀ لوڼو د خپل ترۀ زامنو يعنې د قيس د زامنو سره ودونه وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10332, '1 Chronicles 23:23', '1 Chronicles', 23, 23, '&nbsp;د مرارى دوېم زوئ موشى درې زامن وُو، محلى، عدر او يريموت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10333, '1 Chronicles 23:24', '1 Chronicles', 23, 24, '&nbsp;دا قبيله په قبيله او خاندان په خاندان د ليوى اولاد دے، چې د هغوئ هر يو نومونه ليکلے شوى وُو. د هغۀ د اولاد هر يو کس د مالِک خُدائ په کور کښې خِدمت کولو چې د هغوئ عُمر شل کاله يا د دې نه زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10334, '1 Chronicles 23:25', '1 Chronicles', 23, 25, '&nbsp;داؤد وفرمائيل، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک خپل خلق په امن کړى دى او هغه به په خپله په يروشلم کښې د تل دپاره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10335, '1 Chronicles 23:26', '1 Chronicles', 23, 26, '&nbsp;نو ليويانو ته نور ضرورت نشته چې د مالِک خُدائ د حضور خېمه او هغه ټول سامان يوسى چې په عبادت کښې استعماليږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10336, '1 Chronicles 23:27', '1 Chronicles', 23, 27, '&nbsp;د داؤد د آخرى وصيت په بنياد کله چې ليويان د شلو کالو عُمر ته رسېدل نو د هغوئ ټولو نومونه د خِدمت دپاره ليکلے شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10337, '1 Chronicles 23:28', '1 Chronicles', 23, 28, '&nbsp;او هغوئ ته دا کارونه حواله شوى وُو: د مالِک خُدائ د کور په عبادت کښې د هارون د اولاد مدد کول، د کور د دربارونو او کوټو خيال ساتل، او چې کوم څيزونه مقدس وُو هغه هر څۀ د پليتېدو نه پاک ساتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10338, '1 Chronicles 23:29', '1 Chronicles', 23, 29, '&nbsp;خُدائ پاک ته د پېش کړے شوې روټۍ او د هغه اوړو ذمه وارى اخستل چې په نذرانو کښې استعمالېدل، د خمبيرې نه بغېر نرۍ پخې شوې روټۍ، پخې شوې نذرانې او اوړۀ چې د زيتُونو تېل ورسره ګډ وى، د مالِک خُدائ د کور د نذرانو تَلل او مِقدار معلومول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10339, '1 Chronicles 23:30', '1 Chronicles', 23, 30, '&nbsp;او هر سحر او هر ماښام د مالِک خُدائ په وړاندې ودرېدل، د هغۀ ثناء صِفت کول او د هغۀ شُکر ادا کول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10340, '1 Chronicles 23:31', '1 Chronicles', 23, 31, '&nbsp;او هر کله چې د سبت په ورځ، د نوې مياشتې په اختر او نورو اخترونو باندې مالِک خُدائ ته نذرانې سوزولے شوې، نو هغوئ به مدد کولو. ليويانو به هر ځل د مالِک خُدائ په حضور کښې د سړو د شمېر په مطابق خِدمت کولو، هغوئ په هغه اصُولو باندې عمل کولو چې کوم ورته ښودلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10341, '1 Chronicles 23:32', '1 Chronicles', 23, 32, '&nbsp;هغوئ له د مالِک خُدائ د حضور خېمې او کور د خيال ساتلو او د هغوئ د خپلوانو يعنې د هارون د اولاد اِمامانو د مدد کولو ذمه وارۍ ورکړے شوې وې، چې دا ذمه وارۍ د مالِک خُدائ د کور په خِدمت کښې ادا کېدې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10342, '1 Chronicles 24:1', '1 Chronicles', 24, 1, '&nbsp;دا د خِدمت هغه قبيلې دى چې د هارون اولاد په کښې تقسيم وو. د هارون څلور زامن وُو: ندب، ابيهُو، اِلى‌عزر او اِتمر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10343, '1 Chronicles 24:2', '1 Chronicles', 24, 2, '&nbsp;ندب او ابيهُو د خپل پلار د مرګ نه مخکښې مړۀ شول او د هغوئ اولاد نۀ وو، نو د هغوئ وروڼه اِلى‌عزر او اِتمر اِمامان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10344, '1 Chronicles 24:3', '1 Chronicles', 24, 3, '&nbsp;داؤد بادشاه د هارون د اولاد نه د هغوئ د ذمه وارو په مطابق په ډلو کښې تقسيم کړل. په دې کار کښې د هغۀ مدد د اِلى‌عزر اولاد صدوق او د اِتمر اولاد اخيمُلک کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10345, '1 Chronicles 24:4', '1 Chronicles', 24, 4, '&nbsp;د اِلى‌عزر د اولاد نه شپاړس قبيلې جوړې شوې وې، د اِتمر د اولاد نه اتۀ قبيلې جوړې وې، داسې په دې وجه شوى وُو چې د اِلى‌عزر په اولاد کښې د کورَنو نور مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10346, '1 Chronicles 24:5', '1 Chronicles', 24, 5, '&nbsp;د اِلى‌عزر او اِتمر دواړو په اولاد کښې د مالِک خُدائ په کور کښې د خِدمت دپاره تکړه آفسران او اِمامان وُو نو ټولې ذمه وارۍ مختلفو ډلو ته د پچې په ذريعه حواله شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10347, '1 Chronicles 24:6', '1 Chronicles', 24, 6, '&nbsp;د اِلى‌عزر او د اِتمر اولاد دپاره وار په وار پچه اچولے شوه. نو د هغوئ نومونه د نتنى‌ايل زوئ سمعياه ليکلى وُو چې دا يو ليوے منشى وو. بادشاه، د هغۀ آفسران، صدوق اِمام، د ابياتار زوئ اخيمُلک او د ليوى قبيلې او د اِمامانو د کورَنو مشران ټول د دې ګواهان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10348, '1 Chronicles 24:19', '1 Chronicles', 24, 19, '&nbsp;د دې سړو نومونه د هغوئ د ذمه وارو په مطابق ليکلے شوى وُو چې کله هم هغوئ د مالِک خُدائ کور ته د خپلو هغه ذمه وارو دپاره تلل کوم چې د هغوئ پلار نيکۀ هارون د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د حُکمونو د منلو دپاره مقررې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10349, '1 Chronicles 24:20', '1 Chronicles', 24, 20, '&nbsp;دا د ليوى د اولاد کورَنو نور مشران دى: يهدياه چې د سبو‌اېل په ذريعه د عُمرام اولاد وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
