(10352, '1 Chronicles 24:23', '1 Chronicles', 24, 23, '&nbsp;د عُمر په ترتيب باندې د حبرون زامن دا وُو، يرياه، امرياه، يحزى‌ايل، يقمعام،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
