(10355, '1 Chronicles 24:26', '1 Chronicles', 24, 26, '&nbsp;د مرارى اولاد، محلى، موشى او يعزياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10356, '1 Chronicles 24:27', '1 Chronicles', 24, 27, '&nbsp;د يعزياه درې زامن وُو، سوهم، زکور او عبرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10357, '1 Chronicles 24:30', '1 Chronicles', 24, 30, '&nbsp;د موشى درې زامن وُو، محلى، عدر او يريموت. دا د ليويانو خاندان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10358, '1 Chronicles 24:31', '1 Chronicles', 24, 31, '&nbsp;د هر خاندان مشرانو او کشرانو وروڼو يو شان د هغوئ د ذمه وارو دپاره پچه اچوله، هم هغه شان لکه څنګه چې د هغوئ خپلوانو يعنې د هارون د اولاد اِمامانو وُو. داؤد بادشاه، صدوق، اخيمُلک او د اِمامانو او د ليويانو د کورَنو مشران او د دې ګواهان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10359, '1 Chronicles 25:1', '1 Chronicles', 25, 1, '&nbsp;داؤد بادشاه او د ليويانو مشرانو د ليويانو دا قبيلې خوښې کړې چې د خُدائ پاک پېغام بيانوى، آسف، هيمان او يدوتون. دې سړو به د بينجو، ربابونو او چمټو د موسيقۍ سره پېشګوئې ورکوله. دا د هغه کسانو نومونه دى کوم چې د عبادت د مشرۍ دپاره خوښ کړے شوى وُو، چې هرې قبيلې به هم هغه قِسم خِدمت کولو:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10360, '1 Chronicles 25:2', '1 Chronicles', 25, 2, '&nbsp;د آسف څلورو زامنو زکور، يوسف، نتنياه او اسرى‌لاه، د آسف د مشرۍ لاندې کار کولو. چې کله هم بادشاه حُکم کولو نو آسف به د خُدائ پاک پېغام بيانولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10361, '1 Chronicles 25:3', '1 Chronicles', 25, 3, '&nbsp;د يدوتون شپږو زامنو جدلياه، ضرى، يشعياه، سِمعى، حسبياه او متتياه، د خپل پلار د ښودنې لاندې کار کولو، يدوتون د ربابونو د موسيقۍ سره د خُدائ پاک پېغام بيانولو، حمد‌و‌ثناء يې وئيله او د مالِک خُدائ شُکر يې ادا کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10362, '1 Chronicles 25:4', '1 Chronicles', 25, 4, '&nbsp;د هيمان څوارلس زامنو بُقياه، متنياه، عُزى‌اېل، سبو‌اېل، يريموت، حننياه، حنانى، الياته، جدالتى، روممتى عزر، يسبقاشه، ملوتى، هوتير او محازيوت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10363, '1 Chronicles 25:5', '1 Chronicles', 25, 5, '&nbsp;خُدائ پاک د خپلې وعدې په مطابق هيمان د بادشاه پېغمبر له دا څوارلس زامن او درې لوڼه د دې دپاره ورکړې وې چې هيمان عزتمند شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10364, '1 Chronicles 25:6', '1 Chronicles', 25, 6, '&nbsp;د هغۀ ټولو زامنو د خپل پلار د ښودنې لاندې چمټۍ، بينجو او ربابُونه د مالِک خُدائ د کور په عبادت کښې غږول. او آسف، يدوتون او هيمان د بادشاه د حُکم لاندې کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10365, '1 Chronicles 25:7', '1 Chronicles', 25, 7, '&nbsp;دا څليريشت واړه تجربه‌کار سړى وُو، او د هغوئ خپلوان ليويان تکړه موسيقاران وُو. دا ټول دوه سوه او اتۀ اتيا سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10366, '1 Chronicles 25:8', '1 Chronicles', 25, 8, '&nbsp;هغوئ ته د کارونو ذمه وارۍ حواله کولو دپاره پچه اچولے شوه، کۀ هغوئ ځوانان وُو او يا بوډاګان، کۀ اُستاذان او يا کۀ شاګردان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10367, '1 Chronicles 26:1', '1 Chronicles', 26, 1, '&nbsp;دا هغه ډلې دى چا چې د مالِک خُدائ د کور د څوکيدارانو په توګه خِدمت کولو. د قورح د ډلې د قورى زوئ مسلمياه چې د آسف د خاندان وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10368, '1 Chronicles 26:2', '1 Chronicles', 26, 2, '&nbsp;د هغۀ اووۀ زامن وُو چې د عُمر په ترتيب داسې دى، زکرياه، يديعيل، زبدياه، يتنى‌اېل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
