(10370, '1 Chronicles 26:4', '1 Chronicles', 26, 4, '&nbsp;د عوبيد ادوم هم اتۀ زامن وُو، چې د عُمر په ترتيب داسې دى، سمعياه، يهوزبد، يوآخ، ساکار، نتنى‌ايل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
