(10372, '1 Chronicles 26:8', '1 Chronicles', 26, 8, '&nbsp;د عوبيد ادوم خاندان ټول دوه شپېتۀ ډېر زيات قابل سړى د دې کار دپاره ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10373, '1 Chronicles 26:9', '1 Chronicles', 26, 9, '&nbsp;د مسلمياه خاندان اتلس تکړه سړى ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10374, '1 Chronicles 26:10', '1 Chronicles', 26, 10, '&nbsp;د مرارى د قبيلې حوسه څلور زامن وُو، سِمرى، خپل پلار دې د خپلو زامنو مشر جوړ کړو، اګر چې هغه د ټولو مشر نۀ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10375, '1 Chronicles 26:11', '1 Chronicles', 26, 11, '&nbsp;خِلقياه، طبلياه او زکرياه. د حوسه د خاندان ټول ديارلس کسان د مالِک خُدائ د کور څوکيداران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10376, '1 Chronicles 26:12', '1 Chronicles', 26, 12, '&nbsp;د مالِک خُدائ د کور څوکيداران د هغوئ د کورَنو په مطابق په ډلو کښې تقسيم شوى وُو او هغوئ ته په هغه کور کښې د نورو ليويانو په شان ذمه وارۍ حواله شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10377, '1 Chronicles 26:13', '1 Chronicles', 26, 13, '&nbsp;د هر خاندان وړوکوالى او غټوالى ته کتلو نه بغېر به پچه اچولے شوه چې د کومې يوې دروازې څوکيدارى ورته حواله کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10378, '1 Chronicles 26:14', '1 Chronicles', 26, 14, '&nbsp;د شلمياه د پچې په ذريعه د نمرخاتۀ طرف ته دروازه ووتله او د هغۀ د زوئ زکرياه شمالى طرف ته دروازه ووتله، دا هغه سړ‌ے وو چې همېشه يې د حِکمت مشورې ورکولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10379, '1 Chronicles 26:15', '1 Chronicles', 26, 15, '&nbsp;عوبيد ادوم ته د جنوب طرف ته دروازه حواله شوې وه او د هغۀ زامنو ته د ګودام د کوټو څوکيدارى حواله شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10380, '1 Chronicles 26:16', '1 Chronicles', 26, 16, '&nbsp;سفيم او حوسه ته د نمرپرېواتۀ طرف ته دروازه او په پاسنۍ لار باندې د سلکت دروازه حواله شوې وه. د څوکيدارۍ ذمه وارۍ په يو بل پسې په مقررو وختونو کښې تقسيم کړے شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10381, '1 Chronicles 26:17', '1 Chronicles', 26, 17, '&nbsp;نمرخاتۀ طرف ته هره ورځ شپږو څوکيدارانو کار کولو، په شمالى طرف باندې څلورو او په جنوبى طرف باندې څلورو څوکيدارانو کار کولو. څلور څوکيداران به هره ورځ د ګودام په کوټو باندې مقررولے شول، چې په هره يوه کوټه باندې دوه دوه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10382, '1 Chronicles 26:18', '1 Chronicles', 26, 18, '&nbsp;د نمرپرېواتۀ طرف ته دربار سره په لاره څلور څوکيداران وُو او په خپله په دربار باندې دوه څوکيداران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10383, '1 Chronicles 26:19', '1 Chronicles', 26, 19, '&nbsp;دا د قورح او د مرارى ډلو د څوکيدارۍ ذمه وارۍ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10384, '1 Chronicles 26:20', '1 Chronicles', 26, 20, '&nbsp;نور ليويان د مالِک خُدائ د کور د ګودامونو ذمه وار وُو او په هغه ګودامونو کښې خُدائ پاک ته وقف شوى څيزونه پراتۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10385, '1 Chronicles 26:21', '1 Chronicles', 26, 21, '&nbsp;د جيرسون په ډله کښې د لِبنى د خاندان نه يحى‌ايل مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10386, '1 Chronicles 26:22', '1 Chronicles', 26, 22, '&nbsp;د لعدان دوه نور زامن زيتام او يوايل د مالِک خُدائ د کور د خزانو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10387, '1 Chronicles 26:23', '1 Chronicles', 26, 23, '&nbsp;د عُمرام، اِضهار، حبرون او عُزى‌اېل اولاد ته هم ذمه وارۍ حواله شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10388, '1 Chronicles 26:24', '1 Chronicles', 26, 24, '&nbsp;د موسىٰ زوئ جيرسوم د قبيلې سبو‌اېل د مالِک خُدائ د کور د خزانې مشر آفسر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10389, '1 Chronicles 26:25', '1 Chronicles', 26, 25, '&nbsp;د اِلى‌عزر د طرف نه د جيرسوم خپلوان رحبياه، يشعياه، يورام، زِکرى او سلوميت وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10390, '1 Chronicles 26:26', '1 Chronicles', 26, 26, '&nbsp;سلوميت او د هغۀ خپلوان د هغه خزانو مشران وُو په کومو کښې چې هغه تُحفې پرَتى وې چې هغه داؤد بادشاه، د کورَنو مشرانو او وړو او غټو فوجى آفسرانو مالِک خُدائ ته وقف کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10391, '1 Chronicles 26:27', '1 Chronicles', 26, 27, '&nbsp;هغوئ څۀ هغه مالِ غنيمت واخستلو کوم چې هغوئ په جنګ کښې قبضه کړے وو او دا يې وقف کړو چې د مالِک خُدائ په کور کښې استعمال شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10392, '1 Chronicles 26:28', '1 Chronicles', 26, 28, '&nbsp;سلوميت او د هغۀ خاندان د هغه هر څيز مشران وُو چې کوم د مالِک خُدائ په کور کښې د استعمالېدلو دپاره وقف وُو، سره د هغه تُحفو چې سموئيل پېغمبر، ساؤل بادشاه، د نير زوئ ابنير، او د ضروياه زوئ يوآب راوړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10393, '1 Chronicles 26:29', '1 Chronicles', 26, 29, '&nbsp;د اِضهار په ډله کښې کنعنياه او د هغۀ زامنو ته د مالِک خُدائ د کور نه علاوه ذمه وارۍ حواله شوې وې: هغوئ به حِساب کِتاب ساتلو او د بنى اِسرائيلو لانجې به يې هوارولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10394, '1 Chronicles 26:30', '1 Chronicles', 26, 30, '&nbsp;د حبرون د قبيلې نه حسبياه او د هغۀ اوولس سوه خپلوان، چې تکړه سړى وُو هغوئ د اُردن سيند نمرپرېواتۀ طرف ته په اِسرائيل کښې د مالِک خُدائ د خِدمت او د بادشاه د کار مشران مقرر شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10395, '1 Chronicles 26:31', '1 Chronicles', 26, 31, '&nbsp;يرياه د حبرون د اولاد مشر وو. د داؤد بادشاه د بادشاهۍ په څلوېښتم کال د حبرون د اولاد نسب‌نامه معلومه کړے شوې وه او د دې خاندان تکړه فوجيان موندلے شوى وُو چې د جِلعاد په علاقه يعزير کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10396, '1 Chronicles 26:32', '1 Chronicles', 26, 32, '&nbsp;د يرياه په خپلوانو کښې دوه زره او اووۀ سوه تکړه سړى وُو. داؤد بادشاه هغوئ د اُردن سيند نمرخاتۀ طرف ته ولېږل او هغوئ يې د روبين، جاد او منسى د نيمې قبيلې مشران مقرر کړل. هغوئ د هغه ټولو کارونو ذمه وار وُو چې د هغې تعلق د خُدائ پاک او د بادشاه د خِدمت سره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10397, '1 Chronicles 27:1', '1 Chronicles', 27, 1, '&nbsp;دا د بنى اِسرائيلو د وړو او غټو آفسرانو، او د نورو فوجى آفسرانو تفصيل دے چا چې د بادشاهۍ د فوجى ډلو مشرى کوله. د هرې قبيلې څليريشت زره فوجيانو د کال په يوه مياشت کښې فوجى خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10398, '1 Chronicles 27:23', '1 Chronicles', 27, 23, '&nbsp;د کومو خلقو عُمر چې د شلو کالو نه کم وو نو داؤد بادشاه د هغوئ مردم‌شمارى ونۀ کړه، ځکه چې مالِک خُدائ وعده کړې وه چې هغه به بنى اِسرائيليان د آسمان د ستورو په شان ډېر تېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10399, '1 Chronicles 27:24', '1 Chronicles', 27, 24, '&nbsp;د ضروياه زوئ يوآب مردم‌شمارى شروع کړه، خو مکمله يې نۀ کړه. خُدائ پاک د مردم‌شمارۍ په وجه بنى اِسرائيلو له سزا ورکړه، نو ځکه د داؤد بادشاه په سرکارى حِساب کِتاب کښې د هغې آخرى تعداد ونۀ ليکلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10400, '1 Chronicles 27:32', '1 Chronicles', 27, 32, '&nbsp;د داؤد بادشاه ترۀ يونتن يو تکړه مشير او عالِم وو. هغه او د حکمونى زوئ يحى‌ايل د بادشاه د زامنو د تعليم ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');